function pack(locale){return BANK[ql7Locale(locale)]||BANK.en}
function stylePack(locale){return STYLE_BANK[ql7Locale(locale)]||STYLE_BANK.en}
function resultData(plan){const result=plan?.receipt?.result;return result&&typeof result==='object'?result:{}}
function replaceVars(template='',data={}){return ql7NormalizeSpaces(String(template||'').replace(/\{(\w+)\}/gu,(_,key)=>ql7Str(data[key]??'—')))}
function pickUnique(values,ledger={},seed=''){const rows=ql7Arr(values).filter(Boolean);if(!rows.length)return'';const seen=new Set(ql7Arr(ledger.responseFingerprints));const start=parseInt(ql7StableHash(seed),16)%rows.length;for(let i=0;i<rows.length;i++){const row=rows[(start+i)%rows.length];if(!seen.has(ql7StableHash(row.toLowerCase())))return row}return rows[start]}
function pickNoNewFact(locale='en',ledger={},topic='support_system'){const rows=ql7Arr(NO_NEW_FACT_BANK[locale]||NO_NEW_FACT_BANK.en).filter(Boolean);if(!rows.length)return'';const fingerprints=ql7Arr(ledger?.responseFingerprints).filter(Boolean);const seen=new Set(fingerprints);const base=parseInt(ql7StableHash(`${locale}:${topic}:no-new-fact`),16)%rows.length;const start=(base+fingerprints.length)%rows.length;for(let i=0;i<rows.length;i++){const row=rows[(start+i)%rows.length];if(!seen.has(ql7StableHash(row.toLowerCase())))return row}return rows[start]}
function compactTopicLabel(topic,locale){return getQl7SupportTopicLabel(topic,locale)||getQl7SupportDomain(topic)?.label||topic}
