function escapeRe(value=''){return ql7Str(value).replace(/[.*+?^${}()|[\]\\]/gu,'\\$&')}
function choiceCleanupLabels(plan={},locale='en'){
 const optionLabels=ql7Arr(plan.choices?.options).map(row=>ql7Str(row?.label)).filter(Boolean)
 const topicLabels=CHOICE_PAIR_TOPICS.map(topic=>ql7Str(getQl7SupportTopicLabel(topic,locale))).filter(Boolean)
 return [...new Set([...optionLabels,...topicLabels])].filter(label=>label.length>=2&&label.length<=96).sort((a,b)=>b.length-a.length)
}
function stripGeneratedChoicePairs(text='',plan={},locale='en'){
 const labels=choiceCleanupLabels(plan,locale)
 if(!labels.length)return ql7Str(text)
 const source=labels.map(escapeRe).join('|')
 const pairRe=new RegExp(`(?:^|\\s)(?:${source})(?:\\s*/\\s*(?:${source})){1,4}\\.?`,'giu')
 return ql7NormalizeSpaces(ql7Str(text).replace(pairRe,' '))
}
function choiceBoundSentence(plan={},locale='en',ledger={},category='ambiguousMaterialClarifier',fallback=''){
 let base=''
 if(category==='unrecognizedInput'&&UNRECOGNIZED_COPY[locale])base=UNRECOGNIZED_COPY[locale]
 for(let attempt=0;attempt<48&&!base;attempt+=1){
  const picked=pickQl7HumanVariation(locale,category,{ledger,seed:`${plan.seed}:choices:${plan.topic}:${category}:${attempt}`})||fallback
  const cleaned=stripGeneratedChoicePairs(picked,plan,locale)
  if((NOISE_ASSUMPTION.test(cleaned)||CHOICE_CONTEXT_MISMATCH.test(cleaned)||DOMAIN_CONTEXT_MISMATCH.test(cleaned))&&cleaned!==ql7Str(fallback))continue
  base=cleaned
 }
 if(!base)base=ql7Str(fallback)
 const labels=ql7Arr(plan.choices?.options).map(row=>ql7Str(row?.label)).filter(Boolean).slice(0,4)
 const prefix=CHOICE_HINT_PREFIX[locale]||fallback
 const hint=labels.length?`${prefix} ${labels.join(' / ')}.`:''
 return ql7NormalizeSpaces(`${base} ${hint}`)
}
