function safeKnowledgeBridge(locale,bridge=''){const value=ql7Str(bridge);return hasKnowledgeLocaleLeak(value,locale)||CHOICE_CONTEXT_MISMATCH.test(value)||DOMAIN_CONTEXT_MISMATCH.test(value)?'':value}
function knowledgeSentence(plan,locale){const answer=getQl7SupportKnowledgeAnswer({topic:plan.topic,intent:plan.messageAct,locale,seed:`${plan.seed}:v14-natural-knowledge`});const bridge=safeKnowledgeBridge(locale,pickQl7ProductHowToBridge(locale,plan.topic,{ledger:plan.ledger,seed:`${plan.seed}:knowledge:${plan.topic}`}));if(answer?.text&&!hasKnowledgeLocaleLeak(answer.text,locale))return ql7NormalizeSpaces(`${answer.text} ${bridge}`);const c=getQl7NativeCopy(locale);const label=getQl7SupportTopicLabel(plan.topic,locale)||getQl7SupportDomain(plan.topic)?.label||plan.topic;return ql7NormalizeSpaces(`${c.knowledgeIntro(label)} ${c.knowledgeUse(label)} ${c.knowledgeAccount} ${bridge}`)}
function aiRecommendationSentence(plan,locale,ledger={}){const pack=AI_COPY[locale]||AI_COPY.en;const data=resultData(plan);const exhausted=data.quotaState==='exhausted'||data.canAnalyze===false||Number(data.remainingSec)===0&&Number(data.limitSec)>0;if(exhausted)return pickQl7HumanVariation(locale,'aiQuotaExhausted',{ledger,seed:`${plan.seed}:ai-quota`})||pack.quota;const symbol=data.symbol||plan.marketSignals?.symbol||'BTCUSDT';const timeframe=data.timeframe||plan.marketSignals?.timeframe||'5m';const price=data.price!==undefined&&data.price!==null?data.price:'—';const action=data.action||data.recommendation||data.signal||'HOLD';const confidence=data.confidence!==undefined?`${data.confidence}%`:'—';const template=pickQl7HumanVariation(locale,'aiRecommendationReady',{ledger,seed:`${plan.seed}:ai-ready:${symbol}:${timeframe}:${action}:${confidence}`})||pack.ready;return replaceVars(template,{symbol,timeframe,price,action,confidence})}
